INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES (1, 100, 2, 0.0, "2024/10/31 12:00:00", -416.5, "2030/01/01 14:59:59", 3001, 130011, "ヤマト", 2.1, 3001100, "ミッションねえ……\nちょうどいいや\nどこまで片付けられるか\n賭けをしようじゃないか");
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES (4, 101, 2, 0.0, "2024/10/31 12:00:00", -416.5, "2030/01/01 14:59:59", 3001, 130011, "ヤマト", 5.68, 3001101, "他人から言われた任務を\n言われるままにやるなんざ\n性に合わないんだがね……\nま、報酬は貰っとこうか");
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES (1, 102, 1, 0.0, "2024/10/31 12:00:00", -416.5, "2030/01/01 14:59:59", 3001, 130011, "ヤマト", 0.0, 3001102, "なんだい？　やれンなら\nとっとと済ませちまいな。\nフブキが早くやることやれ\nってボヤいてたよ。");
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES (1, 100, 1, 0.0, "2024/10/31 12:00:00", -416.5, "2030/01/01 14:59:59", 3002, 130211, "フブキ", 0.0, 3002100, "え～？　ぼくに頼みごと～？\nどうしちゃおっかな～\nちゃんとお願いできたら\n考えてあげよっかな～？");
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES (1, 101, 1, 0.0, "2024/10/31 12:00:00", -416.5, "2030/01/01 14:59:59", 3002, 130211, "フブキ", 0.0, 3002101, "ほらほらぁ、これが\n欲しいんでしょ～？\nほんと、しょうがないよね～\nザコおに～いさん♡");
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES (5, 102, 2, 0.0, "2024/10/31 12:00:00", -416.5, "2030/01/01 14:59:59", 3002, 130211, "フブキ", 8.53, 3002102, "へえ～、欲しいんだ～？\nぼくのた・い・せ・つ・な・モ・ノ\nあははっ！　なに考えてんの？\nもうへんふしじゃ～んｗ");
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES (7, 103, 1, 0.0, "2024/10/31 12:00:00", -416.5, "2030/01/01 14:59:59", 3002, 130211, "フブキ", 5.67, 3002103, "なになに～？　もしかしてまた\nおねだりするつもりなんだ？\nとか言って、ほんとはぼくに\n会いたいだけだったりして～？");
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES (1, 104, 1, 0.0, "2024/10/31 12:00:00", -416.5, "2030/01/01 14:59:59", 3002, 130211, "フブキ", 0.0, 3002104, "ザコお兄さんってぇ\n頼み方もワンパなのぉ～？\nもっと必死にならないと\nぼくの心は動かせないよ～？");
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES (3, 300, 3, 0.0, "2024/10/31 12:00:00", -416.5, "2030/01/01 14:59:59", 3004, 130211, "フブキ", 0.0, 3002300, "あのさーザコお兄さん、\nな～んか調子乗ってない？\nぼくのこと、なんでもくれる\nチョロいやつとか思ってたりー？");
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES (7, 301, 7, 0.0, "2024/10/31 12:00:00", -416.5, "2030/01/01 14:59:59", 3005, 130211, "フブキ", 0.0, 3002400, "ざんね～ん♪\nうざいお兄さんには、もうな～んにもあげませ～ん♡\nほんとなっさけなーい♪\nばいば～い♡");
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES (2, 200, 1, 0.0, "2024/10/31 12:00:00", -416.5, "2030/01/01 14:59:59", 3003, 130211, "フブキ", 4.4, 3003200, "きゃはは、ほんと必死～♡\nは～、面白かった。\n笑えたからいいよ～\nそれ、恵んだげる～♪");
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES (7, 201, 7, 0.0, "2024/10/31 12:00:00", -416.5, "2030/01/01 14:59:59", 3003, 130211, "フブキ", 0.0, 3003201, "は～、しょうがないな～♡\nザコお兄さんってば\nほんとよわよわで\n情けないよね～ｗ");
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES (1, 202, 2, 0.0, "2024/10/31 12:00:00", -416.5, "2030/01/01 14:59:59", 3003, 130211, "フブキ", 5.6, 3003202, "お兄さんってば、ぼくがいないと\nほんとザッコザコだよね～\nもっと感謝しろし～♪");
